VIEW = """
  SELECT p.paid_on AS entry_date, 'in'::text AS direction, 'payment'::text AS source_type,
         p.id AS source_id, CASE WHEN p.kind = 'reversal' THEN -p.amount ELSE p.amount END AS amount,
         p.mode::text AS mode, p.loan_id, p.created_at
    FROM payment p
  UNION ALL
  SELECT l.disbursal_date, 'out', 'loan', l.id, l.principal, l.disbursal_mode, l.id, l.created_at
    FROM loan l WHERE l.deleted_at IS NULL
  UNION ALL
  SELECT c.entry_date, c.direction, 'cash_entry', c.id, c.amount, c.mode, NULL, c.created_at
    FROM cash_entry c WHERE c.deleted_at IS NULL
"""
CHARGES = """
  UNION ALL
  SELECT l.disbursal_date, 'in', 'loan_charge', ch.id, ch.amount, l.disbursal_mode, l.id, ch.created_at
    FROM loan_charge ch JOIN loan l ON l.id = ch.loan_id WHERE l.deleted_at IS NULL
"""


def _lock_function(columns: tuple[str, ...]) -> str:
    changed = " OR ".join(f"NEW.{c} IS DISTINCT FROM OLD.{c}" for c in columns)
    return f"""
        CREATE OR REPLACE FUNCTION lt_lock_loan_terms() RETURNS trigger LANGUAGE plpgsql AS $$
        BEGIN
          IF {changed} THEN
            RAISE EXCEPTION 'loan terms are locked once the loan is saved'
              USING ERRCODE = 'insufficient_privilege';
          END IF;
          RETURN NEW;
        END $$;
    """


def _upgrade_rules() -> None:
    op.create_check_constraint(op.f("ck_business_broken_period_default"), "business",
                               "broken_period_default in ('none','first_installment','upfront')")
    op.create_check_constraint(op.f("ck_business_emi_rounding_default"), "business",
                               "emi_rounding_default in (0.01, 1, 5, 10, 50, 100)")
    op.create_check_constraint(op.f("ck_loan_broken_period"), "loan",
                               "broken_period in ('none','first_installment','upfront')")
    op.create_check_constraint(op.f("ck_loan_security_kind"), "loan", "security_kind in ('none','vehicle','land','both')")
    op.create_check_constraint(op.f("ck_loan_advance_installments"), "loan", "advance_installments between 0 and 12")
    # Loans saved before this change: everything lent was handed over.
    op.execute("UPDATE loan SET amount_handed_over = principal")
    # Charges are part of the loan terms: never changed or deleted once saved.
    op.execute("CREATE TRIGGER loan_charge_append_only BEFORE UPDATE OR DELETE ON loan_charge "
               "FOR EACH ROW EXECUTE FUNCTION lt_forbid_change()")
    op.execute("CREATE TRIGGER loan_charge_no_truncate BEFORE TRUNCATE ON loan_charge "
               "FOR EACH STATEMENT EXECUTE FUNCTION lt_forbid_change()")
    op.execute(_lock_function(LOCKED_TERMS))
    # Charges collected when a loan is given are money in on that day (the loan itself is money out).
    op.execute("CREATE OR REPLACE VIEW daily_log AS" + VIEW + CHARGES)


def _downgrade_rules() -> None:
    # A view cannot lose a UNION branch with CREATE OR REPLACE, so drop and recreate it.
    op.execute("DROP VIEW daily_log")
    op.execute("CREATE VIEW daily_log AS" + VIEW)
    op.execute(_lock_function(OLD_LOCKED_TERMS))
    op.execute("DROP TRIGGER IF EXISTS loan_charge_append_only ON loan_charge")
    op.execute("DROP TRIGGER IF EXISTS loan_charge_no_truncate ON loan_charge")
    for table, name in (("loan", "advance_installments"), ("loan", "security_kind"), ("loan", "broken_period"),
                        ("business", "emi_rounding_default"), ("business", "broken_period_default")):
        op.drop_constraint(op.f(f"ck_{table}_{name}"), table, type_="check")
